$started=[datetime]::UtcNow
$method=if($ArenaOnly){'FogRuntimeArenaCheck.Run'}elseif($SparseOnly){'FogRuntimeSparseCheck.Run'}elseif($NoiseOnly){'FogRuntimeNoiseCheck.Run'}elseif($DomainOnly){'FogRuntimeDomainCheck.Run'}elseif($RecoveryOnly){'FogRuntimeRecoveryCheck.Run'}elseif($ScratchOnly){'FogRuntimeScratchCheck.Run'}elseif($LazyOnly){'FogRuntimeLazyCheck.Run'}elseif($AtlasOnly){'FogRuntimeAtlasCheck.Run'}elseif($OwnersOnly){'FogRuntimeOwnersCheck.Run'}elseif($CompactOnly){'FogRuntimeCompactCheck.Run'}elseif($PairOnly){'FogRuntimePairCheck.Run'}elseif($ChannelsOnly){'FogRuntimeChannelsCheck.Run'}elseif($ColorOnly){'FogRuntimeColorCheck.Run'}elseif($VisualOnly){'FogRuntimeVisualCheck.Run'}elseif($MeshOnly){'FogRuntimeMeshCheck.Run'}else{'FogRuntimeSimulationCheck.Run'}
