$proof=Join-Path $output $(if($DomainOnly){'comparison.json'}else{'verification.json'})
if(!(Test-Path -LiteralPath $proof) -or (Get-Item -LiteralPath $proof).LastWriteTimeUtc -lt $started){throw 'Fresh fog simulation proof missing.'}
$result=Get-Content -LiteralPath $proof -Raw|ConvertFrom-Json
if($PublishedOnly){
    foreach($field in @('passed','metadataOnly','rejectedRetained','geometryBeforeCpuConfirmation','meshAndAtlasVolume')){if($result.$field -isnot [bool] -or !$result.$field){throw ('Published render evidence missing or false: '+$field)}}
    foreach($field in @('productionSchedulerTested','wholeHouseSupported','gameHostTested','gpuTimingsMeasured')){if($result.$field -isnot [bool] -or $result.$field){throw ('Published render scope invalid: '+$field)}}
    foreach($field in @('owners','captures','comparisons','negativeControls','legacyCaptures')){if($result.$field -isnot [long] -and $result.$field -isnot [int]){throw ('Published render integer invalid: '+$field)}}
    foreach($field in @('legacyMeanDelta','maxMeanDelta','maxLocalDelta','poisonedCpuDelta','disabledKeywordDelta','staleGenerationDelta')){if(($result.$field -isnot [double] -and $result.$field -isnot [long] -and $result.$field -isnot [int]) -or [double]::IsNaN($result.$field) -or [double]::IsInfinity($result.$field) -or $result.$field -lt 0){throw ('Published render measurement invalid: '+$field)}}
    if($result.owners -ne 2 -or $result.captures -ne 87 -or $result.comparisons -ne 62 -or $result.negativeControls -ne 26 -or $result.legacyCaptures -ne 16 -or $result.legacyMeanDelta -ne 0 -or $result.maxMeanDelta -ge .0001 -or $result.maxLocalDelta -ge .03 -or $result.poisonedCpuDelta -ne 0 -or $result.disabledKeywordDelta -le .0001 -or $result.staleGenerationDelta -le .0001){throw 'Published render coverage incomplete.'}
}
elseif($ArenaFramesOnly){
    foreach($field in @('passed','cachedRepliesAfterExpiry','queuedInputsReplayed','capturedWhilePending','metadataOnlyPending','receiptFirstHandled','pendingResubmitRejected','pendingRetireRetained','generationReuse','lateReplyRejected','pollingHasNoWait','verificationBarriersBetweenBatches')){if($result.$field -isnot [bool] -or !$result.$field){throw ('Arena frames evidence missing or false: '+$field)}}
    foreach($field in @('productionAllocatorTested','rendererTested','wholeHouseSupported','gameHostTested','gpuTimingsMeasured')){if($result.$field -isnot [bool] -or $result.$field){throw ('Arena frames scope invalid: '+$field)}}
    foreach($field in @('frames','owners','committed','rejected','fieldComparisons','ledgerComparisons','atlasComparisons','metadataComparisons')){if($result.$field -isnot [long] -and $result.$field -isnot [int]){throw ('Arena frames integer missing or invalid: '+$field)}}
    if($result.frames -lt 33 -or $result.frames -gt 5000 -or $result.owners -ne 2 -or $result.committed -ne 54 -or $result.rejected -ne 0 -or $result.fieldComparisons -ne 232 -or $result.ledgerComparisons -ne 174 -or $result.atlasComparisons -ne 20 -or $result.metadataComparisons -ne 54){throw 'Arena frames coverage incomplete.'}
}
elseif($ArenaPhysicsOnly){
    foreach($field in @('passed','realSolver','stagedLedger','velocityAlias','packingRollback','shortageRollback','callbackWaitsInFixture','metadataBeforeReceipt','metadataOnlyTested','fractionalVisualClock','borrowedOwnershipValidated','runtimeArenaValidated')){if($result.$field -isnot [bool] -or !$result.$field){throw ('Arena physics evidence missing or false: '+$field)}}
    foreach($field in @('productionAllocatorTested','wholeHouseSupported','gameHostTested','gpuTimingsMeasured')){if($result.$field -isnot [bool] -or $result.$field){throw ('Arena physics scope invalid: '+$field)}}
    foreach($field in @('borrowedInvalidCases','gridX','gridY','gridZ','owners','ticks','fieldComparisons','ledgerComparisons','atlasComparisons','committed','rejected','metadataComparisons')){if($result.$field -isnot [long] -and $result.$field -isnot [int]){throw ('Arena physics integer missing or invalid: '+$field)}}
    if($result.borrowedInvalidCases -ne 11 -or $result.gridX -ne 96 -or $result.gridY -ne 80 -or $result.gridZ -ne 80 -or $result.owners -ne 2 -or $result.ticks -ne 360 -or $result.fieldComparisons -ne 664 -or $result.ledgerComparisons -ne 498 -or $result.atlasComparisons -ne 28 -or $result.committed -lt 161 -or $result.committed -gt 340 -or $result.rejected -ne 2 -or $result.metadataComparisons -ne ($result.committed+$result.rejected+1)){throw 'Arena physics coverage incomplete.'}
}
elseif($ArenaOnly){
    foreach($field in @('passed','shortageRollback','packingRollback','nonfiniteRollback','pendingRemoval','reusedSlot','guttersExact','freeBlocksConserved')){if($result.$field -isnot [bool] -or !$result.$field){throw ('Arena GPU evidence missing or false: '+$field)}}
    foreach($field in @('productionAllocatorTested','fullWallTested','wholeHouseSupported','gameHostTested')){if($result.$field -isnot [bool] -or $result.$field){throw ('Arena GPU scope invalid: '+$field)}}
    foreach($field in @('owners','capacityBlocks','committed','rejected','batchChecks','fieldComparisons','ledgerComparisons')){if($result.$field -isnot [long] -and $result.$field -isnot [int]){throw ('Arena integer missing or invalid: '+$field)}}
    if($result.owners -ne 8 -or $result.capacityBlocks -ne 27 -or $result.committed -ne 47 -or $result.rejected -ne 3 -or $result.batchChecks -ne 15 -or $result.fieldComparisons -ne 480 -or $result.ledgerComparisons -ne 360){throw 'Arena GPU coverage incomplete.'}
}
elseif($SparseOnly){
    foreach($field in @('passed','gameHostTested','wholeHouseSupported','productionAllocatorTested','gpuTimingsMeasured','projectionIsHouseAdmission','recontact','projectionFitsFieldCap')){if($result.$field -isnot [bool]){throw ('Sparse evidence boolean missing or invalid: '+$field)}}
    if(!$result.passed -or $result.gameHostTested -or $result.wholeHouseSupported -or $result.productionAllocatorTested -or $result.gpuTimingsMeasured -or $result.projectionIsHouseAdmission -or $result.ticks -ne 360 -or $result.fieldComparisons -ne 1444 -or $result.ledgerComparisons -ne 1083 -or $result.cpuRawComparisons -ne 16 -or $result.finiteHalfPatterns -ne 63488 -or $result.rawFixtures -ne 3 -or $result.negativeControls -ne 4 -or !$result.recontact -or $result.liveSteps -le 0 -or $result.commonBufferBytes -ne 16 -or $result.comparisonDenseTextureBytes -ne 98304000 -or $result.peakStoredBytes -lt 115200 -or $result.peakOldNewBytes -lt $result.peakStoredBytes -or $result.synchronizedRoundTripMilliseconds -le 0){throw 'Sparse roundtrip evidence incomplete; this does not approve the production allocator.'}
    if($result.liveSteps -gt 361 -or $result.peakStoredBytes -gt 14860800 -or $result.peakOldNewBytes -gt 29721600 -or [double]::IsNaN($result.synchronizedRoundTripMilliseconds) -or [double]::IsInfinity($result.synchronizedRoundTripMilliseconds)){throw 'Sparse evidence exceeds its bounded measurement.'}
    $shared=$result.shared
    foreach($field in @('owners','ticks','fieldComparisons','ledgerComparisons','cpuRawComparisons','denseWorkspaceAndVelocityBytes','peakCandidateFieldBytes','peakEncodedOldNewBytes')){if($shared.$field -isnot [long] -and $shared.$field -isnot [int]){throw ('Shared sparse integer missing or invalid: '+$field)}}
    foreach($field in @('passed','independentStates','productionAllocatorTested','rendererTested','sourceAdmissionTested')){if($shared.$field -isnot [bool]){throw ('Shared sparse boolean missing or invalid: '+$field)}}
    if(!$shared.passed -or !$shared.independentStates -or $shared.productionAllocatorTested -or $shared.rendererTested -or $shared.sourceAdmissionTested -or $shared.owners -ne 8 -or $shared.ticks -ne 360 -or $shared.fieldComparisons -ne 11584 -or $shared.ledgerComparisons -ne 8688 -or $shared.cpuRawComparisons -ne 16 -or $shared.denseWorkspaceAndVelocityBytes -ne 83558400 -or $shared.peakEncodedOldNewBytes -lt 1036800 -or $shared.peakCandidateFieldBytes -gt 98304000 -or $shared.peakCandidateFieldBytes -lt (83558400L+8*8196+16+$shared.peakEncodedOldNewBytes)){throw 'Shared sparse state or candidate field-byte evidence incomplete.'}
    $projection=83558400L+9*$result.peakStoredBytes+8*8196+16
    if($result.projectedEightIdenticalOwnersBytes -ne $projection -or $result.projectionFitsFieldCap -ne ($projection -le 98304000)){throw 'Sparse hypothetical-owner memory projection differs.'}
}
elseif($NoiseOnly){
