}
elseif($DomainOnly){
    if(!$result.collected -or $result.visualAccepted -or $result.frames.Count -ne 12 -or $result.colorSpace -cne 'Linear' -or !@($result.frames|Where-Object{$_.sameSourceWideSmoke -gt 0 -and $_.sameSourceCroppedSmoke -gt 0}).Count){throw 'Domain diagnostic incomplete; this is not visual acceptance.'}
    if(!$result.boundaryIsolated -or $result.probeControlMaxFieldDelta -ne 0 -or @($result.frames|Where-Object{$_.paddingSweep.Count -ne 4}).Count){throw 'Boundary diagnostic lacks its exact control or four padding cases.'}
    foreach($frame in $result.frames){
        $control=$frame.paddingSweep[3]
        if(!$control.allFieldsExact -or !$control.recoveryFlagsExact -or $control.awayMaxDelta -ne 0 -or $control.peakMaxDelta -ne 0 -or $control.grid.x -ne 96 -or $control.grid.y -ne 80 -or $control.grid.z -ne 80 -or $control.smoke -ne $frame.sameSourceWideSmoke){throw 'Boundary probe changed its full-domain control.'}
    }
}
elseif(!$result.passed -or ($RecoveryOnly -and ($result.frames -lt 24 -or !$result.expiredHandleObserved -or !$result.delayedReadbackRetained -or !$result.staleRecoveryRejected -or !$result.pendingDisposeSafe)) -or ($ScratchOnly -and ($result.ticks -ne 360 -or $result.exactFieldComparisons -ne 36 -or $result.owners -ne 3 -or $result.budgetOwners -ne 12 -or $result.budgetBytes -ne 96075776 -or !$result.exactGridSharing -or !$result.persistentIndependent -or !$result.factoryRollback -or !$result.recoveredReleased -or !$result.budgetRejectBeforeFactory)) -or ($LazyOnly -and ($result.frames -ne 5 -or $result.owners -ne 28 -or $result.idleDelta -ne 0 -or $result.maxImageDelta -ge .005 -or $result.maxForegroundDelta -ge .03 -or !$result.delayedClock -or !$result.recoveredReleased -or !$result.reentered -or !$result.sharedEmptyRetained -or !$result.mixedAtlas -or !$result.blueprintAdapter -or !$result.blueprintVisible -or !$result.narrowContact -or !$result.budgetFailureRetainsNeighbor -or !$result.staleRecoveryRetained -or !$result.sourceCutout -or !$result.packingCache -or !$result.dormantSamplingExact -or $result.fullSamplingMs -le 0 -or $result.fullSamplingPackingMs -le 0 -or $result.cachedRenderMs -le 0 -or $result.forcedPackingMs -le 0 -or $result.plainRenderMs -le 0)) -or ($AtlasOnly -and ($result.frames -ne 4 -or $result.owners -ne 3 -or $result.houseLayoutBytes -le 0 -or $result.houseLayoutBytes -gt 134217728 -or !$result.layoutRolled -or !$result.allocationFailureRecovered -or !$result.packingCache -or !$result.packedFieldsExact -or !$result.guardsRetainSimulations -or !$result.cleanup -or $result.maxOrderDelta -ge .000001 -or $result.pairDelta -ge .00001 -or $result.removalDelta -ne 0 -or $result.missingOwnerDelta -le .001 -or $result.edgeDelta -ge .00001 -or $result.occlusionDelta -ne 0 -or $result.translatedDelta -ge .005)) -or ($OwnersOnly -and ($result.owners -ne 3 -or $result.ticks -ne 420 -or $result.frames -ne 3 -or $result.maxImageDelta -ge .005 -or $result.maxForegroundDelta -ge .03 -or $result.minimumEmptyDelta -le .03 -or $result.translatedDelta -ge .005 -or !$result.geometryRetained -or !$result.physicalDetailRetained -or !$result.pigmentIndependent -or !$result.removalIsolated -or !$result.budgetRejectBeforeFactory -or !$result.reservationMismatchDisposed -or !$result.largeRejected -or !$result.recoveredReleased)) -or ($CompactOnly -and ($result.gridX -ne 32 -or $result.gridY -ne 40 -or $result.gridZ -ne 36 -or $result.fields -ne 10 -or $result.ticks -ne 300 -or $result.fieldBytes -ne 3686400 -or !$result.mixedBudgetExact -or !$result.independentOwner -or !$result.recoveredReleased -or !$result.invalidRejected -or !$result.originalGridRetained)) -or ($PairOnly -and ($result.frames -ne 4 -or !$result.orderIndependent -or !$result.singleExact -or !$result.sequentialNegative -or !$result.removalIsolated -or !$result.pooledVisualGuards -or !$result.spanRejected -or !$result.opaqueDepthExact -or !$result.reusedOwnerRetained -or $result.colorSpace -cne 'Linear')) -or ($ChannelsOnly -and ($result.capacity -ne 2 -or $result.independentFieldComparisons -ne 6 -or $result.overlappingVoxels -le 0 -or !$result.inactiveOwnerUnchanged -or !$result.staleRecoveryRejected -or !$result.noEviction -or !$result.removalIsolated -or !$result.recoveredReleased -or !$result.emptySlotClean -or !$result.duplicateTransportRejected -or !$result.smokeOnlyRetained -or !$result.surfaceOnlyRetained -or !$result.factoryReentryRejected -or !$result.factoryDisposeRejected)) -or ($ColorOnly -and ($result.hostColorSpace -cne 'Linear' -or !$result.gammaHostRejected -or !$result.gammaMismatchReproduced -or $result.linearBundleDelta -ge .005)) -or ($VisualOnly -and ($result.colorSpace -cne 'Gamma' -or !$result.shapeEqual -or !$result.pigmentEqual -or !$result.noiseEqual -or $result.frames.Count -ne 6)) -or ($MeshOnly -and ($result.cases -ne 3 -or $result.checkedVertices -le 6)) -or (!$MeshOnly -and !$VisualOnly -and !$ColorOnly -and !$ChannelsOnly -and !$PairOnly -and !$CompactOnly -and !$OwnersOnly -and !$AtlasOnly -and !$LazyOnly -and !$ScratchOnly -and !$RecoveryOnly -and !$DomainOnly -and !$NoiseOnly -and !$SparseOnly -and !$ArenaOnly -and !$ArenaPhysicsOnly -and !$ArenaFramesOnly -and !$PublishedOnly -and ($result.ticks -ne 270 -or $result.exactFieldComparisons -ne 18 -or !$result.released -or !$result.invalidInputsRejected))){throw 'Fog verification evidence incomplete.'}
$bundle=if($PublishedOnly){'artifacts/fog-runtime-assets-candidate/buildworks-fog-v11'}elseif($VisualOnly){'artifacts/fog-runtime-assets-gamma/buildworks-fog-v11'}else{'src/BuildWorks/Assets/FogGhostRuntime/buildworks-fog-v11'}
$sourceReceipt=@{ runtimeArenaSha=(Get-FileHash -LiteralPath (Join-Path $root 'src/BuildWorks/BlueprintFogArena.cs')).Hash; runtimeScratchSha=(Get-FileHash -LiteralPath (Join-Path $root 'src/BuildWorks/BlueprintFogScratch.cs')).Hash; runtimeSha=(Get-FileHash -LiteralPath (Join-Path $root 'src/BuildWorks/BlueprintFogSimulation.cs')).Hash; referenceSha=$hash; bundleSha=(Get-FileHash -LiteralPath (Join-Path $root $bundle)).Hash; completedAtUtc=[datetime]::UtcNow.ToString('o') }
if($SparseOnly){foreach($file in @('FogSparseStorageProbe.cs','FogSparseStorageProbe.compute','FogRuntimeSparseCheck.cs','FogSparseSharedProbe.cs')){$sourceReceipt[$file]=(Get-FileHash -LiteralPath (Join-Path $project ('Assets/Editor/'+$file))).Hash}}
if($ArenaOnly){foreach($file in @('FogRuntimeArenaCheck.cs','FogSparseArenaProbe.compute')){$sourceReceipt[$file]=(Get-FileHash -LiteralPath (Join-Path $project ('Assets/Editor/'+$file))).Hash};$sourceReceipt['snapshotStateSha']=(Get-FileHash -LiteralPath (Join-Path $root 'src/BuildWorks/BlueprintFogSnapshotState.cs')).Hash;$sourceReceipt['inputQueueSha']=(Get-FileHash -LiteralPath (Join-Path $root 'src/BuildWorks/BlueprintFogInputQueue.cs')).Hash}
if($ArenaPhysicsOnly -or $ArenaFramesOnly -or $PublishedOnly){foreach($file in @('FogPublishedRenderCheck.cs','FogArenaFramesCheck.cs','FogArenaPhysicsProbe.cs','FogSnapshotMetadataProbe.compute','FogSparseArenaProbe.compute','FogSparseStorageProbe.cs','FogSparseStorageProbe.compute','FogRuntimeSparseCheck.cs')){$sourceReceipt[$file]=(Get-FileHash -LiteralPath (Join-Path $project ('Assets/Editor/'+$file))).Hash};$sourceReceipt['snapshotStateSha']=(Get-FileHash -LiteralPath (Join-Path $root 'src/BuildWorks/BlueprintFogSnapshotState.cs')).Hash;$sourceReceipt['inputQueueSha']=(Get-FileHash -LiteralPath (Join-Path $root 'src/BuildWorks/BlueprintFogInputQueue.cs')).Hash}
